29	void ASTSelectWithUnionQuery::formatQueryImpl(const FormatSettings & settings, FormatState & state, FormatStateStacked frame) const
30	{
31	    std::string indent_str = settings.one_line ? "" : std::string(4 * frame.indent, ' ');
32	
33	    auto mode_to_str = [&](auto mode)
34	    {
35	        if (mode == SelectUnionMode::ALL)
36	            return "UNION ALL";
37	        else if (mode == SelectUnionMode::DISTINCT)
38	            return "UNION DISTINCT";
39	        else if (mode == SelectUnionMode::INTERSECT)
40	            return "INTERSECT";
41	        else if (mode == SelectUnionMode::EXCEPT)
42	            return "EXCEPT";
43	        return "";
44	    };
45	
46	    for (ASTs::const_iterator it = list_of_selects->children.begin(); it != list_of_selects->children.end(); ++it)
47	    {
48	        if (it != list_of_selects->children.begin())
49	            settings.ostr << settings.nl_or_ws << indent_str << (settings.hilite ? hilite_keyword : "")
50	                          << mode_to_str((is_normalized) ? union_mode : list_of_modes[it - list_of_selects->children.begin() - 1])
51	                          << (settings.hilite ? hilite_none : "");
52	
53	        if (auto * node = (*it)->as<ASTSelectWithUnionQuery>())
54	        {
55	            settings.ostr << settings.nl_or_ws << indent_str;
56	
57	            if (node->list_of_selects->children.size() == 1)
58	            {
59	                (node->list_of_selects->children.at(0))->formatImpl(settings, state, frame);
60	            }
61	            else
62	            {
63	                auto sub_query = std::make_shared<ASTSubquery>();
64	                sub_query->children.push_back(*it);
65	                sub_query->formatImpl(settings, state, frame);
66	            }
67	        }
68	        else
69	        {
70	            if (it != list_of_selects->children.begin())
71	                settings.ostr << settings.nl_or_ws;
72	            (*it)->formatImpl(settings, state, frame);
73	        }
74	    }
75	}
